#include <stdio.h>
#include <stdlib.h>
#define MAX_SIZE 10
typedef struct {
    int items[MAX_SIZE];
    int top;
} Stack;
void push(Stack *s,int value) {
    if(s->top>=MAX_SIZE) {
        printf("Stack overflow\n");
        return;
    }
    s->items[++s->top]=value;
}
int pop(Stack *s) {
    if(s->top<0) {
