questions.answer:
strcpy/strcat 必须确保目标容量足够，源为有效的 NUL 结尾字符串；它们与标准 memcpy 都不允许源、目标有效区重叠。重叠要求应使用 memmove，不能仍把函数称作符合标准的 memcpy。strcmp 按 unsigned char 比较，只要求负、零、正，不要求恰为 -1/0/1。下面代码见本题后的实现；按标准前提使用，并对容量负责。
这是一份教学实现。memmove 通过相等比较扫描重叠关系，避免对无关对象指针使用大小比较；两遍扫描仍是 O(n)，但不是库函数级性能优化。调用者须保证有效缓冲区；strcpy/strcat 还须保证容量和终止符。
#include <stddef.h>

char *my_strcpy(char *dst, const char *src) {
    char *ret = dst;
    while ((*dst++ = *src++) != '\0') { }
    return ret;
}

char *my_strcat(char *dst, const char *src) {
    char *ret = dst;
    while (*dst != '\0') ++dst;
    while ((*dst++ = *src++) != '\0') { }
    return ret;
}

int my_strcmp(const char *a, const char *b) {
    const unsigned char *p = (const unsigned char *)a;
    const unsigned char *q = (const unsigned char *)b;
    while (*p != 0 && *p == *q) { ++p; ++q; }
    return (int)*p - (int)*q;
}

void *my_memcpy(void *dst, const void *src, size_t n) {
    unsigned char *d = dst;
    const unsigned char *s = src;
    for (size_t i = 0; i < n; ++i) d[i] = s[i];
    return dst;
}

/* Detect overlap without ordering unrelated pointers. */
void *my_memmove(void *dst, const void *src, size_t n) {
    unsigned char *d = dst;
    const unsigned char *s = src;
    if (n == 0 || d == s) return dst;
    size_t off = 1;
    while (off < n && d != s + off) ++off;
    if (off < n) {
        for (size_t i = n; i > 0; --i) d[i-1] = s[i-1];
    } else {
        for (size_t i = 0; i < n; ++i) d[i] = s[i];
    }
    return dst;
}

