    const unsigned char *s = src;
    if (n == 0 || d == s) return dst;
    size_t off = 1;
    while (off < n && d != s + off) ++off;
    if (off < n) {
        for (size_t i = n; i > 0; --i) d[i-1] = s[i-1];
    } else {
        for (size_t i = 0; i < n; ++i) d[i] = s[i];
    }
    return dst;
}

