questions.answer:
DFS 可用递归或显式栈，前序为根左右、中序为左根右、后序为左右根；递归额外空间 O(h)，退化树 h 可为 n。BFS 使用 FIFO 队列：先入根，反复出队访问并按顺序入左右子节点，时间 O(n)，辅助空间 O(w)，w 是最大层宽。完整参考实现见本题代码，并处理空树与队列容量。
DFS 要求 visit 非空。BFS 采用便于理解的线性队列，cap 须容纳树的总节点数，容量不足返回 -1 且可能已访问部分节点；循环队列可将占用降至层宽级。
#include <stddef.h>
struct Tree { int value; struct Tree *left, *right; };
typedef void (*Visit)(int);

void preorder(const struct Tree *root, Visit visit) {
    if (root == NULL) return;
    visit(root->value);
    preorder(root->left, visit);
    preorder(root->right, visit);
}
void inorder(const struct Tree *root, Visit visit) {
    if (root == NULL) return;
    inorder(root->left, visit);
    visit(root->value);
    inorder(root->right, visit);
}
void postorder(const struct Tree *root, Visit visit) {
    if (root == NULL) return;
    postorder(root->left, visit);
    postorder(root->right, visit);
    visit(root->value);
}

/* q is caller-owned; cap must fit all nodes queued. */
int breadth_first(const struct Tree *root, Visit visit,
                  const struct Tree **q, size_t cap) {
    if (root == NULL) return 0;
    if (q == NULL || cap == 0 || visit == NULL) return -1;
    size_t front = 0, rear = 0;
    q[rear++] = root;
    while (front < rear) {
        const struct Tree *p = q[front++];
        visit(p->value);
        if (p->left != NULL) {
            if (rear == cap) return -1;
            q[rear++] = p->left;
        }
        if (p->right != NULL) {
            if (rear == cap) return -1;
            q[rear++] = p->right;
        }
    }
    return 0;
}

