questions.answer:
冒泡比较相邻元素并交换，把较大者逐趟推到末尾；选择排序每趟选未排序区最小项与开头交换；插入排序把当前值插入已排序区并移动后续元素；快速排序选枢轴分区后递归处理左右区。本题后给出完整实现；快排采用三路划分并优先递归较短区，以缓解重复值和递归栈问题，但最坏时间仍可为 O(n²)。
所有函数按升序排序；n>0 时 a 须指向至少 n 个可写元素。三路快排处理重复键，较短区递归可使调用栈维持 O(log n)，但并不消除最坏 O(n²) 时间。
#include <stddef.h>

static void swap_int(int *a, int *b) {
    int t = *a; *a = *b; *b = t;
}

void bubble_sort(int *a, size_t n) {
    for (size_t end = n; end > 1; --end) {
        int changed = 0;
        for (size_t j = 1; j < end; ++j) {
            if (a[j-1] > a[j]) {
                swap_int(&a[j-1], &a[j]);
                changed = 1;
            }
        }
        if (!changed) break;
    }
}

void selection_sort(int *a, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        size_t m = i;
        for (size_t j = i + 1; j < n; ++j)
            if (a[j] < a[m]) m = j;
        if (m != i) swap_int(&a[i], &a[m]);
    }
}

void insertion_sort(int *a, size_t n) {
    for (size_t i = 1; i < n; ++i) {
        int value = a[i];
        size_t j = i;
        while (j > 0 && a[j-1] > value) {
            a[j] = a[j-1]; --j;
        }
        a[j] = value;
    }
}

/* Sort [lo, hi), recursively process the shorter side. */
static void quick_range(int *a, size_t lo, size_t hi) {
    while (hi - lo > 1) {
        int pivot = a[lo + (hi-lo)/2];
        size_t lt = lo, i = lo, gt = hi;
        while (i < gt) {
            if (a[i] < pivot) {
                swap_int(&a[lt], &a[i]); ++lt; ++i;
            } else if (a[i] > pivot) {
                --gt; swap_int(&a[i], &a[gt]);
            } else {
                ++i;
            }
        }
        if (lt-lo < hi-gt) {
            quick_range(a, lo, lt); lo = gt;
        } else {
            quick_range(a, gt, hi); hi = lt;
        }
    }
}

void quick_sort(int *a, size_t n) {
    if (n > 1) quick_range(a, 0, n);
}

