questions.answer:
序列应按统一比较规则有序；对数组等支持 O(1) 随机访问的结构，可实现时间 O(log n)，迭代额外空间 O(1)。用 mid=left+(right-left)/2 避免求和溢出，并明确闭区间或半开区间规则。链表不能简单获得同样的随机访问成本，重复键时还需约定找任意/首个/最后一个。
a 在 n>0 时须有效且升序。返回 1 表示找到，返回 0 表示未找到；重复键返回任意匹配，index 可为 NULL。
#include <stddef.h>
int binary_find(const int *a, size_t n, int value,
                size_t *index) {
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi-lo)/2;
        if (a[mid] < value) lo = mid + 1;
        else if (a[mid] > value) hi = mid;
        else {
            if (index != NULL) *index = mid;
            return 1;
        }
    }
    return 0;
}

